// @ts-check
'use strict';
const fs = require('node:fs');
const path = require('node:path');
const { pathToFileURL } = require('node:url');
const { pickTrack } = require('./music');

/** @typedef {import('../../scripts/build-manifest').ManifestEntry} ManifestEntry */

/** Generated by `npm run build-manifest` and committed. */
const MANIFEST = /** @type {ManifestEntry[]} */ (require('../shared/species-manifest.json'));

const SHINY_ODDS = 1 / 10;

/** media/all_balls_atlas.png: one 64 px column per ball type (column 0 is the plain Poké Ball). */
const BALL_ATLAS_COLUMNS = 27;

/** Atlas columns with their own odds; every other column shares OTHER_BALL_ODDS evenly. */
const BALL_ODDS = [
  { column: 0, odds: 0.55 }, // Poké Ball
  { column: 8, odds: 0.2 }, // Great Ball
  { column: 26, odds: 0.13 }, // Ultra Ball
  { column: 15, odds: 0.02 }, // Master Ball
];
const OTHER_BALL_ODDS = 0.1;

/**
 * Which atlas column (ball type) the Pokémon is recalled into.
 * @param {() => number} [rng]
 */
function pickBallColumn(rng = Math.random) {
  const r = rng();
  // Compare against running totals rather than subtracting, so 0.75 lands on the Ultra Ball, not float noise.
  let upTo = 0;
  for (const { column, odds } of BALL_ODDS) {
    upTo += odds;
    if (r < upTo) return column;
  }
  const special = new Set(BALL_ODDS.map((b) => b.column));
  const others = [...Array(BALL_ATLAS_COLUMNS).keys()].filter((c) => !special.has(c));
  return others[Math.min(Math.floor(((r - upTo) / OTHER_BALL_ODDS) * others.length), others.length - 1)];
}

/** Most favorites the Settings page lets you pin. */
const MAX_FAVORITES = 6;
/** In "mixed" mode, how often a favorite shows up instead of a random Pokémon. */
const MIXED_FAVORITE_ODDS = 0.6;

/**
 * Chooses who appears. In "favorites" mode: one of the pinned favorites that
 * is still in the manifest. In "mixed" mode: a favorite 60% of the time and a
 * random pick the rest. Otherwise (or when none of them is left): a
 * uniformly random species from the enabled generations, or from every
 * generation when none of those is in the manifest. Shiny 1 in 10, but only
 * for species that ship shiny GIFs.
 * @param {{ pokemonMode?: 'random' | 'favorites' | 'mixed', favoriteSpecies?: string[], generations?: number[] }} prefs
 * @param {() => number} [rng]
 * @param {ManifestEntry[]} [manifest]
 */
function pickSpecies(prefs, rng = Math.random, manifest = MANIFEST) {
  const usesFavorites = prefs.pokemonMode === 'favorites' || prefs.pokemonMode === 'mixed';
  const favorites = usesFavorites ? manifest.filter((e) => prefs.favoriteSpecies?.includes(e.key)) : [];
  const inGens = manifest.filter((e) => prefs.generations?.includes(e.gen) ?? true);
  const favoriteTurn = favorites.length > 0 && (prefs.pokemonMode !== 'mixed' || rng() < MIXED_FAVORITE_ODDS);
  const pool = favoriteTurn ? favorites : inGens.length ? inGens : manifest;
  const entry = pool[Math.floor(rng() * pool.length)];
  const shiny = entry.hasShiny && rng() < SHINY_ODDS;
  /** @type {'ltr' | 'rtl'} */
  const direction = rng() < 0.5 ? 'ltr' : 'rtl';
  return { entry, shiny, direction };
}

/**
 * The animated idle GIF the Settings page shows next to each name.
 * @param {ManifestEntry} entry
 * @param {string} mediaDir
 */
function spriteUrl(entry, mediaDir) {
  return pathToFileURL(path.join(mediaDir, `gen${entry.gen}`, entry.key, 'default_idle_8fps.gif')).href;
}

/**
 * Turns a pick into the payload the overlay plays.
 * @param {ReturnType<typeof pickSpecies>} pick
 * @param {{ meetingTitle: string, minutesUntil: number, mediaDir: string, meetingLink?: import('./overlay').MeetingLink | null, account?: string | null, cryVolume?: number, musicVolume?: number, rng?: () => number }} opts
 *   cryVolume / musicVolume: 0–1, 0 leaves that sound out
 * @returns {import('./overlay').ScenePayload}
 */
function buildScene({ entry, shiny, direction }, { meetingTitle, minutesUntil, mediaDir, meetingLink = null, account = null, cryVolume = 0.5, musicVolume = 1, rng = Math.random }) {
  const urgent = minutesUntil <= 0;
  const variant = shiny ? 'shiny' : 'default';
  const spriteDir = path.join(mediaDir, `gen${entry.gen}`, entry.key);
  /** @param {string} state */
  const sprite = (state) => pathToFileURL(path.join(spriteDir, `${variant}_${state}_8fps.gif`)).href;
  // PokeAPI/cries files are keyed by National Dex number.
  const cryFile = path.join(mediaDir, 'cries', `${entry.dex}.ogg`);
  return {
    species: entry.key,
    displayName: entry.name,
    shiny,
    isFlyer: entry.isFlyer,
    spriteSize: entry.spriteSize,
    // Everything renders at 128 px: 32 px sprites x4, the 64 px giants x2.
    spriteScale: entry.spriteSize === 64 ? 2 : 4,
    sprites: { walk: sprite('walk'), idle: sprite('idle'), walkLeft: entry.hasLeftFacing ? sprite('walk_left') : null },
    cry: cryVolume > 0 && fs.existsSync(cryFile) ? pathToFileURL(cryFile).href : null,
    // A ball type by rarity each time, for the return animation.
    pokeball: {
      url: pathToFileURL(path.join(mediaDir, 'all_balls_atlas.png')).href,
      column: pickBallColumn(rng),
      columns: BALL_ATLAS_COLUMNS,
    },
    // Battle theme only for the meeting-start alarm; the warning gets a calm track.
    // With music off there is no track, so the sprite doesn't wait for one to start.
    music: musicVolume > 0 ? pickTrack(mediaDir, urgent ? 'battle' : 'normal', rng) : null,
    volume: { cry: cryVolume, music: musicVolume },
    direction,
    // Flyers cruise at the same relative height on every monitor (15-45 % from the top).
    altitude: 0.15 + rng() * 0.3,
    meetingTitle,
    minutesUntil,
    urgent,
    meetingLink,
    account,
  };
}

/** Species grouped by generation, in dex order, for the Settings page's favorite picker. */
function speciesByGen(manifest = MANIFEST) {
  /** @type {Map<number, ManifestEntry[]>} */
  const groups = new Map();
  for (const e of manifest) {
    const list = groups.get(e.gen) ?? [];
    list.push(e);
    groups.set(e.gen, list);
  }
  return [...groups.entries()].sort(([a], [b]) => a - b);
}

module.exports = { MANIFEST, BALL_ATLAS_COLUMNS, pickBallColumn, MAX_FAVORITES, MIXED_FAVORITE_ODDS, pickSpecies, spriteUrl, buildScene, speciesByGen };
